/// The measured face for one request, or None when nothing was measured.
fn table(family: &str, bold: bool, italic: bool) -> Option<&'static [f32; 95]> {
    let key = family.to_ascii_lowercase();
    Some(match (key.as_str(), bold, italic) {
        ("calibri", false, false) => &CALIBRI,
        ("calibri", false, true) => &CALIBRI_I,
        ("calibri", true, false) => &CALIBRI_B,
        ("calibri", true, true) => &CALIBRI_B_I,
        ("arial", false, false) => &ARIAL,
        ("arial", false, true) => &ARIAL_I,
        ("arial", true, false) => &ARIAL_B,
        ("arial", true, true) => &ARIAL_B_I,
        ("montserrat", false, false) => &MONTSERRAT,
        ("montserrat", false, true) => &MONTSERRAT_I,
        ("montserrat", true, false) => &MONTSERRAT_B,
        ("montserrat", true, true) => &MONTSERRAT_B_I,
        ("nunito", false, false) => &NUNITO,
        ("nunito", true, false) => &NUNITO_B,
        ("open sans", false, false) => &OPEN_SANS,
        ("open sans", false, true) => &OPEN_SANS_I,
        ("open sans", true, false) => &OPEN_SANS_B,
        ("open sans", true, true) => &OPEN_SANS_B_I,
        ("fira sans", false, false) => &FIRA_SANS,
        ("source sans pro", false, false) => &SOURCE_SANS_PRO,
        ("caladea", false, false) => &CALADEA,
        ("caladea", false, true) => &CALADEA_I,
        ("caladea", true, false) => &CALADEA_B,
        ("caladea", true, true) => &CALADEA_B_I,
        ("roboto", false, false) => &ROBOTO,
        ("roboto", true, false) => &ROBOTO_B,
        ("ibm plex sans", false, false) => &IBM_PLEX_SANS,
        ("ibm plex sans", true, false) => &IBM_PLEX_SANS_B,
        ("rubik", false, false) => &RUBIK,
        ("rubik", false, true) => &RUBIK_I,
        ("rubik", true, false) => &RUBIK_B,
        ("rubik", true, true) => &RUBIK_B_I,
        ("barlow light", false, false) => &BARLOW_LIGHT,
        ("barlow", false, false) => &BARLOW,
        ("barlow", false, true) => &BARLOW_I,
        ("barlow", true, false) => &BARLOW_B,
        ("barlow", true, true) => &BARLOW_B_I,
        ("oswald", false, false) => &OSWALD,
        ("oswald", true, false) => &OSWALD_B,
        ("ibm plex sans condensed", false, false) => &IBM_PLEX_SANS_CONDENSED,
        ("ibm plex sans condensed", true, false) => &IBM_PLEX_SANS_CONDENSED_B,
        ("merriweather", false, false) => &MERRIWEATHER,
        ("lobster", false, false) => &LOBSTER,
        _ => return None,
    })
}

/// The same face's advances beyond ASCII, or an empty slice.
fn extras(family: &str, bold: bool, italic: bool) -> &'static [(u32, f32)] {
    let key = family.to_ascii_lowercase();
    match (key.as_str(), bold, italic) {
        ("calibri", false, false) => CALIBRI_X,
        ("calibri", false, true) => CALIBRI_I_X,
        ("calibri", true, false) => CALIBRI_B_X,
        ("calibri", true, true) => CALIBRI_B_I_X,
        ("arial", false, false) => ARIAL_X,
        ("arial", false, true) => ARIAL_I_X,
        ("arial", true, false) => ARIAL_B_X,
        ("arial", true, true) => ARIAL_B_I_X,
        ("montserrat", false, false) => MONTSERRAT_X,
        ("montserrat", false, true) => MONTSERRAT_I_X,
        ("montserrat", true, false) => MONTSERRAT_B_X,
        ("montserrat", true, true) => MONTSERRAT_B_I_X,
        ("nunito", false, false) => NUNITO_X,
        ("nunito", true, false) => NUNITO_B_X,
        ("open sans", false, false) => OPEN_SANS_X,
        ("open sans", false, true) => OPEN_SANS_I_X,
        ("open sans", true, false) => OPEN_SANS_B_X,
        ("open sans", true, true) => OPEN_SANS_B_I_X,
        ("fira sans", false, false) => FIRA_SANS_X,
        ("source sans pro", false, false) => SOURCE_SANS_PRO_X,
        ("caladea", false, false) => CALADEA_X,
        ("caladea", false, true) => CALADEA_I_X,
        ("caladea", true, false) => CALADEA_B_X,
        ("caladea", true, true) => CALADEA_B_I_X,
        ("roboto", false, false) => ROBOTO_X,
        ("roboto", true, false) => ROBOTO_B_X,
        ("ibm plex sans", false, false) => IBM_PLEX_SANS_X,
        ("ibm plex sans", true, false) => IBM_PLEX_SANS_B_X,
        ("rubik", false, false) => RUBIK_X,
        ("rubik", false, true) => RUBIK_I_X,
        ("rubik", true, false) => RUBIK_B_X,
        ("rubik", true, true) => RUBIK_B_I_X,
        ("barlow light", false, false) => BARLOW_LIGHT_X,
        ("barlow", false, false) => BARLOW_X,
        ("barlow", false, true) => BARLOW_I_X,
        ("barlow", true, false) => BARLOW_B_X,
        ("barlow", true, true) => BARLOW_B_I_X,
        ("oswald", false, false) => OSWALD_X,
        ("oswald", true, false) => OSWALD_B_X,
        ("ibm plex sans condensed", false, false) => IBM_PLEX_SANS_CONDENSED_X,
        ("ibm plex sans condensed", true, false) => IBM_PLEX_SANS_CONDENSED_B_X,
        ("merriweather", false, false) => MERRIWEATHER_X,
        ("lobster", false, false) => LOBSTER_X,
        _ => &[],
    }
}

/// The design advance of `ch` for this face, in EM units.
pub fn local_advance_em(family: &str, bold: bool, italic: bool, ch: char) -> Option<f32> {
    let cp = ch as u32;
    // ★Only the style that was actually measured answers. Serving a
    // bold request from the upright face looks harmless and is not:
    // Merriweather Bold is about 1% wider than its Regular, which put
    // d08's 38pt titles up to 9pt past where PowerPoint drew them, and
    // the layout still called itself complete. Six of the seventeen
    // families here have no bold face on this machine; their bold text
    // is declined rather than set on the wrong advances. Whether a
    // SYNTHESISED bold even advances like its upright is unmeasured
    // (S577c, parked), so there is nothing to fall back ON.
    if (32..127).contains(&cp) {
        let t = table(family, bold, italic)?;
        return Some(t[cp as usize - 32]);
    }
    // Beyond ASCII the tables are sparse: a face carries only the
    // characters it actually has, so a miss here is a real answer --
    // the caller declines the run rather than advancing a glyph that
    // is not in the font.
    let src = extras(family, bold, italic);
    match src.binary_search_by_key(&cp, |e| e.0) {
        Ok(i) => Some(src[i].1),
        Err(_) => None,
    }
}

/// Whether any face of `family` was measured.
pub fn local_family_supported(family: &str) -> bool {
    table(family, false, false).is_some()
        || table(family, true, false).is_some()
}
